"""Regenerate pip compatibility exports, or check them without changing files."""
import argparse
from pathlib import Path
import subprocess
import sys

ROOT = Path(__file__).resolve().parents[1]
EXTRAS = ('--extra', 'database', '--extra', 'login')
EXPORTS = {'requirements.txt': (), 'requirements-test.txt': ('--group', 'test')}
HEADER = ('# Generated by: python scripts/dependencies.py\n'
          '# Edit pyproject.toml, src/provider/pyproject.toml or src/wechat_linux/pyproject.toml.\n'
          '# Versions come from uv.lock; do not edit this file by hand.\n')


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true', help='Check the lock and exports without writing files')
    args = parser.parse_args(argv)
    try:
        if not args.check:
            subprocess.run(['uv', 'lock'], cwd=ROOT, check=True)
        generated = {}
        for filename, groups in EXPORTS.items():
            result = subprocess.run(['uv', 'export', '--locked', '--no-emit-project', '--no-emit-local',
                '--no-hashes', '--no-header', '--no-annotate', *EXTRAS, *groups],
                cwd=ROOT, stdout=subprocess.PIPE, text=True, encoding='utf-8', check=True)
            generated[filename] = HEADER+result.stdout
    except FileNotFoundError:
        parser.exit(1, 'uv was not found. Install the version required by pyproject.toml.\n')
    except subprocess.CalledProcessError:
        parser.exit(1, 'Dependency resolution/export failed. Run python scripts/dependencies.py after editing dependencies.\n')
    changed = []
    for filename, expected in generated.items():
        path = ROOT/filename
        if args.check:
            if not path.is_file() or path.read_text(encoding='utf-8') != expected:
                changed.append(filename)
        else:
            path.write_text(expected, encoding='utf-8', newline='\n')
    if changed:
        parser.exit(1, 'Outdated dependency exports: '+', '.join(changed)+'. Run python scripts/dependencies.py.\n')
    print('Dependency lock and exports match.' if args.check else 'Updated dependency lock and pip exports.')
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
